ECO = '\nset block [ord::get_db_block]\nset before {}\nset original_placement {}\nforeach inst [$block getInsts] {\n set pins {}\n foreach pin [$inst getITerms] {dict set pins [[$pin getMTerm] getName] [$pin getNet]}\n dict set before [$inst getName] [list [[$inst getMaster] getName] $pins]\n dict set original_placement [$inst getName] [list [$inst getLocation] [$inst getOrient] [$inst getPlacementStatus]]\n if {[$inst getPlacementStatus] eq "PLACED"} {$inst setPlacementStatus FIRM}\n}\nset oldnets [llength [$block getNets]]\nset original_ports {}\nforeach port [$block getBTerms] {dict set original_ports [$port getName] [$port getNet]}\n\n\nif {[llength [info commands sta::sta_to_db_pin]]!=1} {error "Missing native STA-to-physical pin binding"}\nset pin_by_name {}\nforeach pin [get_pins -hierarchical *] {\n set fullname [get_full_name $pin]\n if {[dict exists $pin_by_name $fullname]} {error "Duplicate STA pin identity"}\n dict set pin_by_name $fullname $pin\n}\nset resolved_pins {}\nforeach {name expected_master delay_master delay_count expected_port} {TARGET_PAIRS} {\n set matches {}\n set candidate $name\n while {1} {\n  if {[dict exists $pin_by_name $candidate]} {dict set matches [dict get $pin_by_name $candidate] 1}\n  set next [string map [list "\\\\\\\\" "\\\\"] $candidate]\n  if {$next eq $candidate} {break}\n  set candidate $next\n }\n if {[dict size $matches]!=1} {error "Missing or ambiguous measured STA pin $name"}\n set sta_pin [lindex [dict keys $matches] 0]\n set pin [sta::sta_to_db_pin $sta_pin]\n if {$pin eq "NULL" || [$pin getIoType] ne "INPUT"} {error "Measured STA pin has no physical input binding"}\n set inst [$pin getInst]\n if {[[$inst getMaster] getName] ne $expected_master} {error "Wrong physical master for $name"}\n if {[dict exists $resolved_pins $name]} {error "Duplicate measured target"}\n dict set resolved_pins $name $pin\n puts "NSSOC_NATIVE_PIN_BINDING $name -> [$inst getName]/[[$pin getMTerm] getName]"\n}\nif {[dict size $resolved_pins]!=TARGET_COUNT} {error "Incomplete native pin census"}\nset changes {}\nset index 0\nforeach {name expected_master delay_master delay_count expected_port} {TARGET_PAIRS} {\n set slash [string last / $name]\n set ti [[dict get $resolved_pins $name] getInst]\n if {$ti eq "NULL" || [[$ti getMaster] getName] ne $expected_master} {error "Measured target master mismatch"}\n set sink [dict get $resolved_pins $name]\n if {$sink eq "NULL" || [$sink getIoType] ne "INPUT"} {error "Target input mismatch"}\n set net [$sink getNet]\n if {$net eq "NULL"} {error "Disconnected target"}\n set drivers {}\n foreach pin [$net getITerms] {if {[$pin getIoType] eq "OUTPUT"} {lappend drivers $pin}}\n set ports [$net getBTerms]\n if {[llength $ports]} {\n  if {[llength $ports]!=1 || [llength $drivers]!=0} {error "Ambiguous boundary driver"}\n  set port [lindex $ports 0]\n  if {[$port getIoType] ne "INPUT" || [$port getName] ne $expected_port} {error "Measured input port identity mismatch"}\n } elseif {[llength $drivers]!=1} {error "Nonunique original driver"}\n set master [[ord::get_db] findMaster $delay_master]\n if {$master eq "NULL" || $delay_count<1 || $delay_count>2} {error "Invalid measured native delay chain"}\n set current $net\n for {set stage 0} {$stage<$delay_count} {incr stage} {\n  set stem [format "nssoc_rx_sized_hold_%03d_%d" $index $stage]\n  set netname [format "%s_out" $stem]\n  if {[$block findInst $stem] ne "NULL" || [$block findNet $netname] ne "NULL"} {error "ECO collision"}\n  set inst [odb::dbInst_create $block $master $stem]\n  set next [odb::dbNet_create $block $netname]\n  [$inst findITerm A] connect $current\n  [$inst findITerm X] connect $next\n  set current $next\n  $inst setOrient [$ti getOrient]\n  $inst setLocation {*}[$ti getLocation]\n  $inst setPlacementStatus PLACED\n }\n $sink disconnect\n $sink connect $current\n dict set changes $sink $current\n puts "NSSOC_POST174_IDENTITY $index $name $expected_master $delay_master $delay_count"\n incr index\n}\nif {$index!=TARGET_COUNT || [llength [$block getInsts]]!=[dict size $before]+DELAY_COUNT || [llength [$block getNets]]!=$oldnets+DELAY_COUNT || [dict size $changes]!=TARGET_COUNT} {error "Wrong repair census"}\nforeach inst [$block getInsts] {\n set name [$inst getName]\n if {![dict exists $before $name]} {continue}\n lassign [dict get $before $name] master pins\n if {[[$inst getMaster] getName] ne $master} {error "Original master changed"}\n foreach pin [$inst getITerms] {\n  set expected [dict get $pins [[$pin getMTerm] getName]]\n  if {[dict exists $changes $pin]} {set expected [dict get $changes $pin]}\n  if {[$pin getNet] ne $expected} {error "Unexpected incidence change"}\n }\n}\nputs "NSSOC_NEW_RX_MEASURED_CELLS_IDENTITY_VERIFIED"\n\nif {[llength [$block getBTerms]]!=[dict size $original_ports]} {error "Port census changed"}\nforeach port [$block getBTerms] {if {[$port getNet] ne [dict get $original_ports [$port getName]]} {error "External port connectivity changed"}}\n'
RESTORE='\nforeach inst [$block getInsts] {\n set name [$inst getName]\n if {![dict exists $original_placement $name]} {continue}\n lassign [dict get $original_placement $name] location orientation status\n if {[$inst getLocation] ne $location || [$inst getOrient] ne $orientation} {error "Original placement moved"}\n $inst setPlacementStatus $status\n}\nputs "NSSOC_ORIGINAL_PLACEMENT_UNCHANGED_AND_STATUSES_RESTORED"\n'
class AckHoldECO(ElectricalPostCTS):
 id='NSSOC.AckHoldECO'
 name='Insert measured hold delays on the reset-sized new RX candidate'
 def get_script_path(self):
  s=Path(super().get_script_path()).read_text()
  rows=json.loads((Path(__file__).resolve().parents[3]/'ack-chip-branches/hold-selected.json').read_text())
  assert rows and len({r['sink']for r in rows})==len(rows)
  target_count=len(rows);delay_count=sum(r['delay_count']for r in rows)
  assert all(r['delay_count']in (1,2)for r in rows)
  pairs=[]
  for r in rows:
   assert r['worst_setup_slack_ns']>=r['delay_count'] and r['delay_master']=='sg13g2_dlygate4sd3_1'
   name=r['sink']
   assert not any(c in name+r['master']for c in '{}\n\r')
   pairs.extend(['{'+name+'}','{'+r['master']+'}','{'+r['delay_master']+'}',str(r['delay_count']),'{'+r['expected_port']+'}'])
  start=s.index('# Buffer I/O');end=s.index('report_floating_nets -verbose',start)
  s=s[:start]+ECO.replace('TARGET_PAIRS',' '.join(pairs)).replace('TARGET_COUNT',str(target_count)).replace('DELAY_COUNT',str(delay_count))+'\n'+s[end:]
  assert 'log_cmd repair_design' not in s and 'unset_propagated_clock [all_clocks]'not in s
  assert s.count('write_views')==1
  s=s.replace('write_views',RESTORE+'\nwrite_views')
  p=Path(self.step_dir)/'ack_hold_eco.tcl';p.write_text(s);return str(p)
@Flow.factory.register()
class AckChipHoldRepair(Interfaces):
 Steps=[AckHoldECO]+[type('Hold'+n,(BranchSTA,),dict(id='NSSOC.Hold'+n,corner=c))for n,c in CORNERS]
